<h1>Review Queue</h1><p>Review closed trades and keep follow-up work visible.</p>
<div class="card table-wrap"><table><thead><tr><th>Trade</th><th>Symbol</th><th>Side</th><th>Closed</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td>#<?=e($r['trade_id'])?></td><td><?=e($r['symbol'])?></td><td><?=e(ucfirst($r['side']))?></td><td><?=e($r['closed_at'])?></td><td><?=e($r['review_due_at']??'—')?></td><td><?=e(ucfirst(str_replace('_',' ',$r['review_status'])))?></td><td><a href="/review/<?=e($r['trade_id'])?>">Review</a></td></tr><?php endforeach;if(!$reviews):?><tr><td colspan="7" class="muted">No reviews in the queue.</td></tr><?php endif;?></tbody></table></div>
